// Builds the GM Screen's "prep sheet" kit for one system from its generated
// Adventure Prep builder, so the Adventure tool draws the very same page:
//   public/prep-sheet/<CODE>.css  the builder's page CSS, scoped to .advh-sheet
//   public/prep-sheet/<CODE>.js   the builder's page renderers (previewParts, buildSB, …)
// Called by scripts/make-session-builders.mjs — never edit the output by hand.

// ── CSS: keep the printed page's rules, re-rooted from .page to .advh-sheet ──
// The builder's own editor UI (sidebar, inputs, buttons) is dropped; anything
// that is not page-scoped but styles a page block (e.g. a skin's `.read-aloud`)
// is prefixed with .advh-sheet so it can never reach the rest of the GM Screen.
const PAGE_CLASS = /^(page-banner|page-inner|page-bottom-band|adventure-title|adventure-subtitle|header-meta|sl|gold|sl-green|p-section|p-text|p-keep|det-grid|det-k|det-hooks|rt-[\w-]+|clue-item|clue-hdr|loc-name|loc-dq|loc-sub|loc-desc|loc-links|loc-lbl|loc-tag|location-block|enc-[\w-]+|npc-block|mob-block|entry-name|entry-desc|entry-meta|sb-(?!.*-input)[\w-]+|stat-block|sbt-[\w-]+|hp-pip|full-width|reward-stats|haz-item|read-aloud|trk-[\w-]+|map-keys|mod-[\w-]+|columns|dcc-ico|hook-item|hp-row|pb-[\w-]+|lotr-[\w-]+|db-[\w-]+|sd-[\w-]+|sh-[\w-]+|je-[\w-]+|jp-[\w-]+|jr-[\w-]+|tv-[\w-]+|fp-[\w-]+|eye-[\w-]+|woe|ok|bad)$/;
const DROP = /(^|[\s>+~(,])(html|body)\b|\.preview-area|\.sidebar|::?-webkit-scrollbar|::selection|\.ui-|#[\w-]/;

function splitTop(str, sep) {
  const out = []; let depth = 0, cur = '', q = null;
  for (let i = 0; i < str.length; i++) {
    const c = str[i];
    if (q) { cur += c; if (c === q && str[i - 1] !== '\\') q = null; continue; }
    if (c === '"' || c === "'") { q = c; cur += c; continue; }
    if (c === '(' || c === '[') depth++;
    if (c === ')' || c === ']') depth--;
    if (c === sep && depth === 0) { out.push(cur); cur = ''; continue; }
    cur += c;
  }
  out.push(cur);
  return out;
}

function scopeSelector(sel) {
  sel = sel.trim();
  if (!sel || DROP.test(sel)) return null;
  if (/:root\b/.test(sel)) return sel.replace(/:root\b/g, '.advh-sheet');
  if (/\.page(?![\w-])/.test(sel)) return sel.replace(/\.page(?![\w-])/g, '.advh-sheet');
  const classes = (sel.match(/\.([\w-]+)/g) || []).map(c => c.slice(1));
  if (!classes.length || !PAGE_CLASS.test(classes[0])) return null;
  return '.advh-sheet ' + sel;
}

// A small brace-aware CSS walker: rules, @media/@supports (recursed),
// @font-face/@keyframes (kept whole), @media print / @page / @import (dropped).
function scopeCss(css) {
  css = css.replace(/\/\*[\s\S]*?\*\//g, '');
  let out = '', i = 0;
  while (i < css.length) {
    const open = css.indexOf('{', i);
    if (open < 0) break;
    const head = css.slice(i, open).trim();
    // find the matching close brace
    let depth = 1, j = open + 1;
    while (j < css.length && depth) { if (css[j] === '{') depth++; else if (css[j] === '}') depth--; j++; }
    const inner = css.slice(open + 1, j - 1);
    i = j;
    if (!head) continue;
    if (head[0] === '@') {
      if (/^@(font-face|keyframes|-webkit-keyframes)/.test(head)) out += head + '{' + inner + '}\n';
      else if (/^@media/.test(head) && !/\bprint\b/.test(head)) { const r = scopeCss(inner); if (r.trim()) out += head + '{\n' + r + '}\n'; }
      else if (/^@supports/.test(head)) { const r = scopeCss(inner); if (r.trim()) out += head + '{\n' + r + '}\n'; }
      continue;
    }
    // a stray ";" before a selector (e.g. after an @import) belongs to nothing
    const sels = splitTop(head.replace(/^[^{]*;/, ''), ',').map(scopeSelector).filter(Boolean);
    if (sels.length) out += sels.join(',') + '{' + inner.trim() + '}\n';
  }
  return out;
}

export function sheetCss(builderHtml) {
  const css = [...builderHtml.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(m => m[1]).join('\n');
  return '/* GENERATED by scripts/make-session-builders.mjs (prep-sheet-bundle.mjs) — the Adventure Prep page, scoped for the GM Screen. */\n' + scopeCss(css);
}

// ── JS: the page renderers, lifted verbatim from the generated builder ──
function fnSource(src, name) {
  const re = new RegExp('(^|\\n)function ' + name.replace(/\$/g, '\\$') + '\\s*\\(');
  const m = re.exec(src); if (!m) throw new Error('prep-sheet: no function ' + name);
  const start = m.index + m[1].length;
  const end = skipCode(src, src.indexOf('{', start) + 1, true);
  if (end < 0) throw new Error('prep-sheet: unbalanced function ' + name);
  return src.slice(start, end);
}
// Scan JS from i until the "}" that closes the current block (returns the index
// after it). Strings, comments, regex literals and nested template literals
// (`…${ … `…` … }…`) are skipped properly.
function skipCode(src, i, untilClose) {
  let depth = 0;
  for (; i < src.length; i++) {
    const c = src[i];
    if (c === '"' || c === "'") { for (i++; i < src.length && src[i] !== c; i++) if (src[i] === '\\') i++; continue; }
    if (c === '`') { i = skipTemplate(src, i + 1); if (i < 0) return -1; continue; }
    if (c === '/' && src[i + 1] === '/') { i = src.indexOf('\n', i); if (i < 0) return -1; continue; }
    if (c === '/' && src[i + 1] === '*') { i = src.indexOf('*/', i) + 1; continue; }
    if (c === '/') {
      let k = i - 1; while (k >= 0 && /\s/.test(src[k])) k--;
      if (k < 0 || /[(,=:[!&|?{};+\-*%<>~^]/.test(src[k]) || /\breturn$/.test(src.slice(Math.max(0, k - 5), k + 1))) {
        let cls = false;
        for (i++; i < src.length; i++) { const d = src[i]; if (d === '\\') { i++; continue; } if (d === '[') cls = true; else if (d === ']') cls = false; else if (d === '/' && !cls) break; }
        continue;
      }
    }
    if (c === '{') depth++;
    else if (c === '}') { if (depth === 0 && untilClose) return i + 1; depth--; }
  }
  return -1;
}
// From just inside a backtick, return the index of its closing backtick.
function skipTemplate(src, i) {
  for (; i < src.length; i++) {
    const c = src[i];
    if (c === '\\') { i++; continue; }
    if (c === '`') return i;
    if (c === '$' && src[i + 1] === '{') { i = skipCode(src, i + 2, true); if (i < 0) return -1; i--; }
  }
  return -1;
}
const FNS = ['escH', 'escA', 'fmtText', 'modOn', 'travelCfg', 'vehCfg', 'sysSections', '_secBlock', '_mline', '_mbadge',
  'xLines', 'trackerLine', 'locBlockInner', 'locBlock', 'buildSB', 'previewFactions', 'previewTravel', 'previewVehicles',
  'previewSections', 'plugPreview', 'previewParts', 'applyGradients'];

export function sheetJs(builderHtml, { code, sbConfig, extJs }) {
  const fns = FNS.map(n => fnSource(builderHtml, n)).join('\n');
  return `/* GENERATED by scripts/make-session-builders.mjs (prep-sheet-bundle.mjs) — the Adventure Prep page renderers for the GM Screen. */
(function(){
var state = {};
var PREP_SYS = ${JSON.stringify(code.toLowerCase())}, PREP_CODE = ${JSON.stringify(code)};
var PREG = window.PREP_REGISTRY || null;
var PLUG = { travel: {} };
var _hbMobs = [];
function v(){ return ''; } function setVal(){} function setText(){} function autosave(){} function renderNow(){}
function _hasQuestName(){ return PREP_CODE === 'DB' || PREP_CODE === 'PB'; }
${sbConfig}
${fns}
try {
${extJs}
} catch (e) { if (window.console) console.warn('prep-sheet ' + PREP_CODE + ': system add-on skipped', e); }
window.PREP_SHEET = window.PREP_SHEET || {};
window.PREP_SHEET[PREP_CODE] = {
  parts: function (st) { state = st || {}; PREG = window.PREP_REGISTRY || PREG; return previewParts(); },
  statBlock: function (sb) { return buildSB(sb || {}).outerHTML; },
  sceneBody: function (l) { return locBlockInner(l || {}); },
  fmt: fmtText,
  gradients: applyGradients,
  trackerLine: trackerLine,
  factions: function (st) { state = st || {}; return previewFactions(); },
  travel: function (st) { state = st || {}; return previewTravel(); },
  vehicles: function (st) { state = st || {}; return previewVehicles(); },
  sections: function (st, tab) { state = st || {}; return previewSections(tab); },
  plug: function (st, where) { state = st || {}; const a = []; try { if (typeof PLUG.preview === 'function') (PLUG.preview(where) || []).forEach(h => a.push(h)); } catch (e) {} return a; }
};
})();
`;
}
